fn strange_sort_list_helper(s: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    // `first` is just a permutation of the input (here we keep the input order).
    let first = s;
    let n = first.len();

    // Build the second list by front–back interleaving of `first`.
    let mut second = Vec::with_capacity(n);
    for i in 0..n {
        let idx = if i % 2 == 0 {
            // even i: take from the front
            i / 2
        } else {
            // odd i: take from the back
            n - ((i - 1) / 2) - 1
        };
        second.push(first[idx]);
    }

    (first, second)
}

