fn main() {
    let input = vec![3, 1, 4, 1, 5, 9];
    let (first, second) = strange_sort_list_helper(input.clone());

    // first is just input in this implementation
    assert_eq!(first, input);

    // second is [first[0], first[5], first[1], first[4], first[2], first[3]]
    assert_eq!(second, vec![3, 9, 1, 5, 4, 1]);

    println!("first  = {:?}", first);
    println!("second = {:?}", second);
}